// Service worker: caches the whole game so it loads fast and works offline after the first visit.
// The file list and the CACHE VERSION live in sw-precache.js (generated by tools/build-precache.ps1).
// Bump the version (run the script) whenever any game file changes: the new worker installs in the background,
// then deletes old caches; the page reloads on the next menu screen (see js/core/pwa.js).
importScripts('sw-precache.js');

const CACHE_NAME = `finfury-cache-v${self.CACHE_VERSION}`;
const SCOPE = self.registration.scope;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    // every local file must be cached for the install to succeed ('reload' = bypass the HTTP cache)
    await Promise.all(self.PRECACHE_URLS.map((path) =>
      cache.add(new Request(new URL(path, SCOPE).href, { cache: 'reload' }))));
    // Phaser comes from the CDN: cache it too, but don't fail the install if the CDN is unreachable right now
    try { await cache.add(new Request(self.PHASER_URL, { mode: 'cors' })); } catch (e) { /* cached on first successful use */ }
    await self.skipWaiting();             // take over as soon as installed
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('finfury-cache-') && k !== CACHE_NAME).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  const ours = url.origin === self.location.origin && url.href.startsWith(SCOPE);
  const phaser = url.href === self.PHASER_URL;
  if (!ours && !phaser) return;           // anything else goes straight to the network

  // iPhone Safari requests <video> with Range headers and needs proper 206 answers, also from the cache
  if (req.headers.has('range')) {
    event.respondWith(rangeResponse(req));
    return;
  }
  event.respondWith(cacheFirst(req));
});

async function cacheFirst(req) {
  const cache = await caches.open(CACHE_NAME);
  // ignoreSearch: "index.html?scene=..." and "./?x" still hit the cached page
  const hit = await cache.match(req, { ignoreSearch: true });
  if (hit) return hit;
  try {
    const res = await fetch(req);
    if (res && res.ok && (res.type === 'basic' || res.type === 'cors')) cache.put(req, res.clone());
    return res;
  } catch (err) {
    // offline and not cached: for page loads fall back to the cached start page
    if (req.mode === 'navigate') {
      const fallback = await cache.match(new URL('./index.html', SCOPE).href);
      if (fallback) return fallback;
    }
    throw err;
  }
}

/** Answer a Range request from the cached full file (206 Partial Content); if it isn't cached use the network. */
async function rangeResponse(req) {
  const cache = await caches.open(CACHE_NAME);
  const hit = await cache.match(req.url, { ignoreSearch: true });
  if (!hit) return fetch(req);
  const buffer = await hit.arrayBuffer();
  const total = buffer.byteLength;
  const m = /bytes=(\d*)-(\d*)/.exec(req.headers.get('range') || '');
  let start = m && m[1] !== '' ? parseInt(m[1], 10) : 0;
  let end = m && m[2] !== '' ? parseInt(m[2], 10) : total - 1;
  if (m && m[1] === '' && m[2] !== '') { start = Math.max(0, total - parseInt(m[2], 10)); end = total - 1; }   // suffix range
  end = Math.min(end, total - 1);
  if (start > end || start >= total) {
    return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${total}` } });
  }
  return new Response(buffer.slice(start, end + 1), {
    status: 206,
    statusText: 'Partial Content',
    headers: {
      'Content-Type': hit.headers.get('Content-Type') || 'application/octet-stream',
      'Content-Length': String(end - start + 1),
      'Content-Range': `bytes ${start}-${end}/${total}`,
      'Accept-Ranges': 'bytes',
    },
  });
}
